import{_ as a,o,c as t,a3 as i}from"./chunks/framework.rPoJfhSN.js";const m=JSON.parse('{"title":"Introducción","description":"","frontmatter":{},"headers":[],"relativePath":"guia/introduccion.md","filePath":"guia/introduccion.md","lastUpdated":null}'),d={name:"guia/introduccion.md"};function n(r,e,s,c,l,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to &quot;Introducción&quot;">​</a></h1><p>Plazora es un marketplace multivendedor construido con Laravel. Reúne en una misma aplicación un escaparate público, una cuenta de cliente, un panel para vendedores y un panel administrativo con permisos.</p><h2 id="propuesta-de-valor" tabindex="-1">Propuesta de valor <a class="header-anchor" href="#propuesta-de-valor" aria-label="Permalink to &quot;Propuesta de valor&quot;">​</a></h2><p>Plazora está pensado como un producto entregable y controlable por quien lo adquiere:</p><ul><li><strong>Completamente en español:</strong> tienda, panel administrativo, panel vendedor, validaciones, alertas y documentación se presentan en español natural.</li><li><strong>Stack moderno:</strong> Laravel 13 sobre PHP 8.5, assets administrados con Vite y dependencias versionadas.</li><li><strong>Infraestructura propia:</strong> el entorno recomendado es una VPS Ubuntu Server con Nginx, PHP-FPM y MySQL administrada por el propietario.</li><li><strong>Documentación incluida:</strong> el código se acompaña de contexto funcional, técnico, operativo y de seguridad.</li><li><strong>Sin dependencia obligatoria del proveedor:</strong> después de recibir y validar el ZIP, el comprador puede respaldar el proyecto en su repositorio privado y mantenerlo mediante Git.</li></ul><p>La documentación forma parte del producto y se publica junto con la aplicación mediante <code>npm run build</code>.</p><h2 id="alcance-actual" tabindex="-1">Alcance actual <a class="header-anchor" href="#alcance-actual" aria-label="Permalink to &quot;Alcance actual&quot;">​</a></h2><ul><li>Catálogo de productos físicos y digitales, categorías jerárquicas, marcas, etiquetas, atributos y variantes.</li><li>Carrito, lista de deseos, cupones, direcciones, envíos, checkout y reseñas.</li><li>Pedidos separados por tienda, comisiones administrativas y cartera del vendedor.</li><li>PayPal, Stripe Checkout y Razorpay como pasarelas configurables.</li><li>Alta de vendedores, perfil de tienda, verificación KYC y solicitudes de retiro.</li><li>Administración de contenido, promociones, anuncios, páginas, contactos y suscriptores.</li><li>SEO básico, sitemap, configuración desde base de datos y localización al español.</li></ul><h2 id="superficies-de-la-aplicacion" tabindex="-1">Superficies de la aplicación <a class="header-anchor" href="#superficies-de-la-aplicacion" aria-label="Permalink to &quot;Superficies de la aplicación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Superficie</th><th>Audiencia</th><th>Acceso</th><th>Responsabilidad</th></tr></thead><tbody><tr><td>Tienda pública</td><td>Visitantes</td><td><code>/</code></td><td>Descubrimiento, catálogo, tiendas y contenido</td></tr><tr><td>Cuenta de cliente</td><td>Clientes autenticados</td><td>Rutas web protegidas</td><td>Perfil, carrito, pedidos, reseñas y descargas</td></tr><tr><td>Panel de vendedor</td><td>Vendedores verificados</td><td><code>/vendor</code></td><td>Productos, pedidos, tienda, cartera y retiros</td></tr><tr><td>Panel administrativo</td><td>Personal interno</td><td><code>/admin</code></td><td>Gobierno de la plataforma, permisos y configuración</td></tr><tr><td>Documentación</td><td>Público</td><td><code>/docs/</code></td><td>Contexto técnico, funcional y operativo</td></tr></tbody></table><h2 id="estado-y-fuente-de-verdad" tabindex="-1">Estado y fuente de verdad <a class="header-anchor" href="#estado-y-fuente-de-verdad" aria-label="Permalink to &quot;Estado y fuente de verdad&quot;">​</a></h2><p>Esta documentación se deriva del código, las rutas, los modelos, los servicios y el esquema de datos presentes en el repositorio. Cuando la documentación contradiga al código, <strong>el código describe el comportamiento ejecutable</strong>, pero la discrepancia debe corregirse en ambos lugares.</p><h2 id="convenciones-del-producto" tabindex="-1">Convenciones del producto <a class="header-anchor" href="#convenciones-del-producto" aria-label="Permalink to &quot;Convenciones del producto&quot;">​</a></h2><ul><li>El sistema, el repositorio y la base de datos se identifican como <strong>Plazora</strong>.</li><li>La base de datos principal se llama <code>plazora</code>; las variantes por entorno pueden usar sufijos como <code>plazora_testing</code>.</li><li>PHP 8.5 es la única versión soportada por esta entrega.</li><li>La recepción inicial se realiza mediante ZIP y el mantenimiento posterior mediante un repositorio GitHub privado. Consulta <a href="/docs/guia/entrega-y-versionado.html">Entrega y versionado</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Producto en evolución</p><p>Hay flujos que requieren endurecimiento antes de operar con dinero real, especialmente idempotencia de pagos, transacciones de pedidos, acreditación de carteras y rotación de credenciales. Consulta <a href="/docs/operacion/seguridad.html">Seguridad</a> y <a href="/docs/negocio/pedidos-pagos.html">Pedidos y pagos</a>.</p></div><h2 id="como-mantener-esta-guia" tabindex="-1">Cómo mantener esta guía <a class="header-anchor" href="#como-mantener-esta-guia" aria-label="Permalink to &quot;Cómo mantener esta guía&quot;">​</a></h2><p>Actualiza la documentación en el mismo cambio que modifique reglas de negocio, variables de entorno, permisos, estructura de datos, pasos de despliegue o integraciones. El comando <code>npm run build</code> compila la interfaz y publica también esta documentación.</p>',17)])])}const g=a(d,[["render",n]]);export{m as __pageData,g as default};
